mapper.select:
SELECT fair_date_id , operation_date , capacity , entry_start_time , entry_end_time FROM fair_dates WHERE fair_id = #{fairId} AND operation_date IN
#{operationDate}
ORDER BY operation_date ASC FOR UPDATE

SELECT COUNT(*)
  FROM reservations
 WHERE fair_id = #{fairId}
   AND visit_date = #{visitDate}
   AND reservation_type = 'ADVANCE'
   AND status IN ('PENDING_PAYMENT', 'CONFIRMED', 'CHECKED_IN')

mapper.update:
UPDATE reservations
   SET visit_date = #{visitDate}
     , updated_at = #{now}
 WHERE reservation_id = #{reservationId}
   AND status = 'CONFIRMED'
